import{_ as n,C as r,c as o,o as s,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Manufacturing Settings","description":"","frontmatter":{},"headers":[],"relativePath":"master/manufacturing/settings.md","filePath":"master/manufacturing/settings.md","lastUpdated":1791532126000}'),l={name:"master/manufacturing/settings.md"};function u(c,e,d,g,p,h){const a=r("ImagePopup");return s(),o("div",null,[e[0]||(e[0]=t('<h1 id="manufacturing-settings" tabindex="-1">Manufacturing Settings <a class="header-anchor" href="#manufacturing-settings" aria-label="Permalink to &quot;Manufacturing Settings&quot;">​</a></h1><p>The <strong>Manufacturing Settings</strong> page allows you to enable or disable the core capabilities of the Manufacturing module based on your production workflow.<br> These options decide how production is planned, executed, and tracked across your shop floor — from simple manufacturing orders to advanced multi-step routings with work orders and dependencies.</p><h2 id="manage-operations" tabindex="-1">Manage Operations <a class="header-anchor" href="#manage-operations" aria-label="Permalink to &quot;Manage Operations&quot;">​</a></h2><p>Navigate to <strong><code>Settings → Manufacturing → Manage Operations</code></strong> as shown below.</p>',4)),i(a,{src:"/images1/manufacturing/manufacturing-settings-operations.png",alt:"Manufacturing Manage Operations Settings"}),e[1]||(e[1]=t('<ul><li><p><strong>Work Orders:</strong> Enable this option to execute manufacturing operations at designated <a href="./configurations/work-centers.html">Work Centers</a>. Turning this on activates the <a href="./operations/work-orders.html">Work Orders</a> menu, so each step of a manufacturing order (cutting, assembly, packaging, etc.) can be scheduled, started, paused, and validated individually with real-time tracking. Once enabled, a quick link <strong><code>Configure work centers</code></strong> appears so you can set up your shop floor right away.</p></li><li><p><strong>Work Order Dependencies:</strong> Enable this to define the <strong>sequence</strong> in which work orders must be processed. With dependencies turned on, a work order will only become ready once all its predecessors are completed. This is configured per <a href="./products/bills-of-material.html">Bill of Material</a> in the <strong>Miscellaneous</strong> tab. Enabling this option automatically enables <strong>Work Orders</strong> above.</p><blockquote><p><strong>Save Changes:</strong> Click to apply your operation settings.</p></blockquote></li></ul><h3 id="use-case" tabindex="-1"><strong>Use Case</strong> <a class="header-anchor" href="#use-case" aria-label="Permalink to &quot;**Use Case**&quot;">​</a></h3><p>Enabling <strong>Work Orders</strong> is essential for businesses with multi-step production processes that need shop-floor scheduling, capacity planning, and operator tracking.<br> Add <strong>Work Order Dependencies</strong> when certain operations must wait for others to finish (e.g. <em>Painting</em> can only start after <em>Assembly</em> is complete).</p><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>The <strong>Manufacturing Settings</strong> area lets you customize:</p><ul><li>Whether production is executed as a single manufacturing order or split into detailed work orders.</li><li>Whether work order sequences/dependencies are enforced.</li><li>Whether by-products are tracked alongside finished goods.</li><li>The default lead time used to plan upcoming production.</li></ul><p>Enable only the capabilities your operations need to keep the manufacturing workflow lean and efficient.</p><blockquote><p><strong>Next step:</strong> Once settings are in place, follow the setup order in the <a href="./operations/manufacturing-orders.html">Manufacturing Orders</a> guide — it includes the complete start-to-end flow chart.</p></blockquote>',8))])}const b=n(l,[["render",u]]);export{f as __pageData,b as default};
